(ROOT/'native_owner.py').write_text("import json,sys,pathlib,datetime,time,hashlib,base64\nfrom urllib.parse import urlparse\nfrom playwright.sync_api import sync_playwright\ncfg=json.load(sys.stdin);assert cfg['account_id']==1843;ROOT=pathlib.Path('/control');seen={};seq=0\ndef now():return datetime.datetime.now(datetime.timezone.utc).isoformat()\ndef sha(v):return hashlib.sha256(str(v).encode()).hexdigest()\ndef claims(t):\n try:\n  p=t.split('.')[1];return json.loads(base64.urlsafe_b64decode(p+'='*(-len(p)%4)))\n except:return {}\ndef emit(event,**kw):\n with (ROOT/'native-1843.jsonl').open('a') as f:f.write(json.dumps({'at':now(),'event':event,'account_id':1843,**kw},ensure_ascii=False)+'\\n')\ndef clean(u):\n p=urlparse(u);return p.scheme+'://'+p.netloc+p.path\ndef onrequest(r):\n a=r.headers.get('authorization','');t=a[7:] if a.lower().startswith('bearer ') else '';c=claims(t)\n if t and c.get('client_id')=='clio-playground-web':\n  seen[sha(t)]=t;pathlib.Path('/tmp/native-token.json').write_text(json.dumps({'token':t}));pathlib.Path('/tmp/native-token.json').chmod(0o600)\n  emit('native_token',token_sha256=sha(t),sid_sha256=sha(c.get('sid','')),user_id_sha256=sha(c.get('user_id','')),client_id=c.get('client_id'),host=urlparse(r.url).hostname)\ndef onresponse(r):\n u=urlparse(r.url)\n if u.hostname and (u.hostname.endswith('adobelogin.com') or u.hostname=='firefly-3p.ff.adobe.io'):\n  emit('http_finish',status=r.status,host=u.hostname,path=u.path[:180])\nwith sync_playwright() as pw:\n p=cfg['proxy_config'];proxy={'server':p['protocol']+'://'+p['host']+':'+str(p['port'])}\n if p.get('username'):proxy.update(username=p['username'],password=p.get('password') or '')\n browser=pw.chromium.launch(executable_path='/chrome/chrome-linux64/chrome',headless=True,proxy=proxy,args=['--remote-debugging-port=9222','--remote-debugging-address=127.0.0.1'])\n ctx=browser.new_context(viewport={'width':1365,'height':950},locale='en-US');ctx.on('request',onrequest);ctx.on('response',onresponse)\n page=ctx.new_page();page.goto('https://firefly.adobe.com/generate/image',wait_until='domcontentloaded',timeout=60000);page.wait_for_timeout(25000)\n # No imported Cookie or access token: every session is created by the browser's normal login UI.\n b=page.get_by_role('button',name='Sign in',exact=True)\n if b.count()==1 and b.is_visible():b.click();page.wait_for_timeout(5000)\n def snapshot(label):\n  states=[]\n  for index,p in enumerate(ctx.pages):\n   if p.is_closed():continue\n   try:states.append({'index':index,'url':clean(p.url),'title':p.title(),'text':p.locator('body').inner_text(timeout=5000)[:7000],'accessibility':p.locator('body').aria_snapshot(timeout=5000)[:10000]})\n   except Exception as ex:states.append({'index':index,'url':clean(p.url),'error_class':type(ex).__name__})\n  value={'at':now(),'label':label,'pages':states,'native_token_count':len(seen)}\n  (ROOT/'native-ui.json').write_text(json.dumps(value,ensure_ascii=False));emit('ui_snapshot',label=label,pages=states,native_token_count=len(seen))\n snapshot('initial_signin')\n deadline=time.time()+900\n while time.time()<deadline and not (ROOT/'abort-all').exists():\n  path=ROOT/'native-command.json'\n  if path.exists():\n   cmd=json.loads(path.read_text())\n   if cmd['seq']>seq:\n    seq=cmd['seq'];target=ctx.pages[cmd.get('page_index',len(ctx.pages)-1)]\n    try:\n     op=cmd['op']\n     if op=='fill_email':target.locator(cmd['selector']).fill(cfg['email'])\n     elif op=='fill_password':\n      assert cfg.get('password');target.locator(cmd['selector']).fill(cfg['password'])\n     elif op=='click':target.get_by_role(cmd.get('role','button'),name=cmd['name'],exact=True).click(timeout=12000)\n     elif op=='goto':\n      assert cmd['url'] in ['https://firefly.adobe.com/generate/image','https://account.adobe.com/'];target.goto(cmd['url'],wait_until='domcontentloaded',timeout=45000)\n     elif op=='snapshot':pass\n     else:raise RuntimeError('unsupported_action')\n     target.wait_for_timeout(3000);snapshot('command_'+str(seq));emit('command_done',seq=seq,op=op)\n    except Exception as ex:emit('command_error',seq=seq,error_class=type(ex).__name__);snapshot('error_'+str(seq))\n  try:page.wait_for_timeout(500)\n  except:time.sleep(0.5)\n browser.close();emit('owner_done')\n")
